function validate([people]) {
  if (!Array.isArray(people) || people.length < 1 || people.length > 2000) return 'people needs 1 to 2000 entries.';
  for (const person of people) {
    if (!Array.isArray(person) || person.length !== 2) return 'Each person is a pair [h, k].';
    const [h, k] = person;
    if (!Number.isInteger(h) || h < 0 || h > 1e6) return 'Each height is a whole number from 0 to 10^6.';
    if (!Number.isInteger(k) || k < 0 || k >= people.length) return 'Each k is from 0 to people.length - 1.';
  }
  // Taller people first (ties by k): each person can only count those placed before them.
  const order = [...people].sort((a, b) => b[0] - a[0] || a[1] - b[1]);
  for (let i = 0; i < order.length; i++) {
    if (order[i][1] > i) return 'These people cannot stand in any line: some k is too large.';
    if (i > 0 && order[i][0] === order[i - 1][0] && order[i][1] === order[i - 1][1]) return 'Two people of the same height cannot have the same k.';
  }
  return null;
}

