function reconstructQueue(people) {
  // Fill the line from the front. The next person must already see exactly k people at least
  // as tall; among those who do, the shortest must go first.
  const n = people.length;
  const used = new Array(n).fill(false);
  const seen = new Array(n).fill(0);
  const line = [];
  for (let step = 0; step < n; step++) {
    let pick = -1;
    for (let i = 0; i < n; i++) {
      if (used[i] || seen[i] !== people[i][1]) continue;
      if (pick === -1 || people[i][0] < people[pick][0]) pick = i;
    }
    used[pick] = true;
    line.push([people[pick][0], people[pick][1]]);
    for (let i = 0; i < n; i++) {
      if (!used[i] && people[pick][0] >= people[i][0]) seen[i]++;
    }
  }
  return line;
}

