function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  let top;
  if (size === 'large') top = rand() < 0.5 ? 1000000 : 50;
  else top = rand() < 0.5 ? 3 : 1000000;
  // Pick a real line first, describe it, then scramble the description.
  const heights = Array.from({ length: n }, () => Math.floor(rand() * (top + 1)));
  const people = heights.map((h, j) => {
    let k = 0;
    for (let t = 0; t < j; t++) if (heights[t] >= h) k++;
    return [h, k];
  });
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [people[i], people[j]] = [people[j], people[i]];
  }
  return [people];
}
